def test_preview():
    '''
    Test endpoint
    POST /preview
    '''
    my_image = open(asset('elephant-wikimedia.png'), 'rb')

    with get_test_client() as test_client:
        response = test_client.post('/preview',
                                    headers={'x-access-token': get_token()},
                                    data={ 'image': my_image})
